<?php
namespace App\Policies;
use App\Models\{ConstructionWorkPackageTask,User}; use App\Policies\Concerns\CompanyOwnedPolicy;
class ConstructionWorkPackageTaskPolicy { use CompanyOwnedPolicy; public function viewAny(User $u):bool{return $this->canForResource($u,'view_any_construction_work_package_task');} public function view(User $u,ConstructionWorkPackageTask $r):bool{return $this->canForRecord($u,'view_construction_work_package_task',$r);} public function create(User $u):bool{return $this->canForResource($u,'create_construction_work_package_task');} public function update(User $u,ConstructionWorkPackageTask $r):bool{return in_array($r->status,['planned','in_progress','awaiting_inspection'],true)&&$this->canForRecord($u,'update_construction_work_package_task',$r);} public function delete(User $u,ConstructionWorkPackageTask $r):bool{return $r->status==='planned'&&!$r->progressUpdates()->exists()&&!$r->inspections()->exists()&&!$r->issues()->exists()&&!$r->delays()->exists()&&$this->canForRecord($u,'delete_construction_work_package_task',$r);} public function start(User $u,ConstructionWorkPackageTask $r):bool{return $this->canForRecord($u,'start_construction_work_package_task',$r);} public function complete(User $u,ConstructionWorkPackageTask $r):bool{return $this->canForRecord($u,'complete_construction_work_package_task',$r);} public function cancel(User $u,ConstructionWorkPackageTask $r):bool{return $this->canForRecord($u,'cancel_construction_work_package_task',$r);} public function recordProgress(User $u,ConstructionWorkPackageTask $r):bool{return $this->canForRecord($u,'create_construction_progress_update',$r);} public function createInspection(User $u,ConstructionWorkPackageTask $r):bool{return $this->canForRecord($u,'create_construction_inspection',$r);} }
